RN:=IF(O>REF(C,1) AND C<O,1,0);
RP:=IF(O<REF(C,1) AND C>O,1,0);
RG:=O>0 AND C>0 AND REF(C,1)>0;
READY:=BARSCOUNT(C)>=262 AND REF(COUNT(RG,260),1)=260;
RA01:IF(READY,100*(REF(SUM(RN,20),1)/20-REF(SUM(RN,240),21)/240),DRAWNULL);
RA02:IF(READY,100*(REF(SUM(RP,20),1)/20-REF(SUM(RP,240),21)/240),DRAWNULL);
